// Only the documented flat gateway envelope is accepted. Discard everything else before side effects.
return $input.all().flatMap((item, index) => {
  const body = item.json.body;
  if (!body || Array.isArray(body) || typeof body !== 'object' || body.data !== undefined || body.event !== 'messages.upsert') return [];
  const key = body.key;
  if (!key || key.fromMe !== false || typeof key.id !== 'string' || !key.id.trim() || key.id.length > 256) return [];
  // Direct phone JIDs only: excludes groups, status, broadcasts and newsletters.
  if (typeof key.remoteJid !== 'string' || key.remoteJid !== key.remoteJid.trim() || !/^[0-9]{5,15}@s\.whatsapp\.net$/.test(key.remoteJid)) return [];
  const text = body.messageType === 'conversation' ? body.message?.conversation : body.messageType === 'extendedTextMessage' ? body.message?.extendedTextMessage?.text : undefined;
  if (typeof text !== 'string' || !text.trim() || text.length > 65536) return [];
  return [{ json: { body: { key: { id: key.id, fromMe: false, remoteJid: key.remoteJid }, message: { conversation: text } }, dedupe_key: JSON.stringify([key.remoteJid, key.id]) }, pairedItem: { item: index } }];
});

// Calculate Reading Latency
const text = $json.body?.message?.conversation || $json.body?.text || "";
const words = text.split(/\s+/).filter(Boolean).length;
const delay = Math.min(Math.max(800 + (words * 220), 1200), 4000);
return { read_delay_ms: delay };

// Calculate Dynamic Typing Delay
const text = $json.ai_response || "Hello! How can I help you today?";
const base = text.length * 35;
const jitter = 0.85 + (Math.random() * 0.30);
const finalDelay = Math.min(Math.max(Math.round(base * jitter), 1800), 8500);
return { typing_delay_ms: finalDelay, reply_text: text };
